import{_ as d,o as r,c as o,a0 as a}from"./chunks/framework.Czf8PZMA.js";const c=JSON.parse('{"title":"Modular House 美国市场 · 标准与竞品动态跟踪清单（L2 雷达）","description":"","frontmatter":{},"headers":[],"relativePath":"l2/10-tracking-list.md","filePath":"l2/10-tracking-list.md","lastUpdated":null}'),e={name:"l2/10-tracking-list.md"};function n(s,t,l,h,i,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="modular-house-美国市场-·-标准与竞品动态跟踪清单-l2-雷达" tabindex="-1">Modular House 美国市场 · 标准与竞品动态跟踪清单（L2 雷达） <a class="header-anchor" href="#modular-house-美国市场-·-标准与竞品动态跟踪清单-l2-雷达" aria-label="Permalink to &quot;Modular House 美国市场 · 标准与竞品动态跟踪清单（L2 雷达）&quot;">​</a></h1><blockquote><p>📌 <strong>平台 L2「动态雷达」的落地点</strong>：分品类竞品对标 + 标准/法规异动。</p><ul><li><strong>用途</strong>：作为「标准与竞品动态跟踪」的完整条目清单，后续叠 cron 自动生成「标准异动简报 / 竞品月报」，并有选择地发布到平台（中文主题，i18n 预留英文版）。</li><li><strong>跟踪节奏</strong>：每个条目标 <code>频率</code>（周/月/季/年/事件驱动）与 <code>触发器</code>（触发一次核对/更新的条件）。</li><li><strong>对标原则</strong>：竞品按<strong>类别</strong>维护「当前最先进对标目标」，随新品/认证动态刷新；不只列名单，明示「为什么它是该类标杆」。</li></ul></blockquote><hr><h2 id="a-结构性决策锚-先读这段-规范所有条目" tabindex="-1">A. 结构性决策锚（先读这段，规范所有条目） <a class="header-anchor" href="#a-结构性决策锚-先读这段-规范所有条目" aria-label="Permalink to &quot;A. 结构性决策锚（先读这段，规范所有条目）&quot;">​</a></h2><ul><li><strong>更新频率总约定</strong>：标准条款（ASTM/AISC/NDS/ACI 等）→ 季度核对版本号；法规（加州/联邦）→ 月度；竞品（分品类）→ 周度扫描 + 事件驱动（ESR/融资/倒闭/新品）；进口/关税 → 事件驱动。</li><li><strong>每个条目推荐落库方式</strong>：<code>read_me</code>（一条跟踪项 + metadata.category + framing 标签）→ 供平台「动态」专区调用。</li><li><strong>英文版预留</strong>：清单字段含 <code>EN</code> 列，未来一键 i18n。</li><li><strong>来源层级</strong>：主来源 = 官方标准组织（ICC/DOI/ASTM/AISC/NDS/ACI/HCD/IHCDA）+ 权威网站（boxabl.com/technical-docs、ARCAT/Sweets/4specs）+ 检索核验；次级 = 新闻/研报，需交叉验证后发布。</li></ul><hr><h2 id="b-分品类竞品对标-每类「最先进对标目标」-动态刷新-⭐" tabindex="-1">B. 分品类竞品对标（每类「最先进对标目标」，动态刷新）⭐ <a class="header-anchor" href="#b-分品类竞品对标-每类「最先进对标目标」-动态刷新-⭐" aria-label="Permalink to &quot;B. 分品类竞品对标（每类「最先进对标目标」，动态刷新）⭐&quot;">​</a></h2><blockquote><p>每类下述「对标标杆」= 当前该类最先进/最具代表性的美国或对美供应商，作为中方买家对标对象。新品/认证/财务异动即触发刷新。</p></blockquote><h3 id="b1-整机-集成模块-full-modular-building" tabindex="-1">B1. 整机/集成模块（Full Modular Building） <a class="header-anchor" href="#b1-整机-集成模块-full-modular-building" aria-label="Permalink to &quot;B1. 整机/集成模块（Full Modular Building）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞品</th><th>类别标杆理由</th><th>跟踪点</th><th>频率</th></tr></thead><tbody><tr><td><strong>Boxabl</strong></td><td>主动式量产、单一产品线、HCD商业制造商、ESR-4725</td><td>新品/plan set/安装手册更新、ESR、降价、经销商网络</td><td>周</td></tr><tr><td><strong>Plant Prefab</strong></td><td>木框架、Rialto 62kft²工厂、CloudConnect snap MEP、约50%工期缩减</td><td>新工厂产能、BIM/MEP快接新品、项目落地</td><td>周</td></tr><tr><td><strong>Stack Modular</strong></td><td>钢模块多高层（the Walk Norwalk 373户/516模块）；整合商模式</td><td>新项目、层高突破、供应链做法</td><td>周</td></tr><tr><td><strong>CIMC-MBS</strong></td><td>中资出海标杆、全钢角柱锁紧、加州派检验赴华工厂、至多30层</td><td>加州项目、层高、节点设计公开</td><td>周</td></tr><tr><td><strong>Guerdon</strong></td><td>Type IIIA 获批、ICC NTA 认证体系</td><td>厂房资质/NTA报告更新</td><td>月</td></tr><tr><td><strong>Autovol</strong></td><td>木框架自动化产线、加州检验员工厂批准</td><td>产能、新认证</td><td>月</td></tr><tr><td><strong>Factory_OS / Harbinger（倒闭）</strong></td><td>⚠️ 行业教训：2026.2 WARN 关闭</td><td>作为「扩张风险」对照案例</td><td>事件</td></tr></tbody></table><h3 id="b2-结构分项-structural-trade-suppliers" tabindex="-1">B2. 结构分项（Structural Trade Suppliers） <a class="header-anchor" href="#b2-结构分项-structural-trade-suppliers" aria-label="Permalink to &quot;B2. 结构分项（Structural Trade Suppliers）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞品</th><th>类别标杆理由</th><th>跟踪点</th><th>频率</th></tr></thead><tbody><tr><td><strong>钢结构（AISC Qc/Qa 工厂）</strong></td><td>美标 AISC 认证钢构厂的对标水平</td><td>AISC 认证名录新增、AWS D1.8 升级</td><td>季</td></tr><tr><td><strong>混凝土/UHPC（ICC-ES ESR 持有者）</strong></td><td>UHPC 体系 ESR-5874 级别；对比中国盈创 3D 打印</td><td>新 UHPC ESR 报告、配合比公开</td><td>季</td></tr><tr><td><strong>木结构（PRG-320 CLT 厂）</strong></td><td>美 CLT 厂（如 Katerra 遗产/新兴厂）对标</td><td>CLT 认证厂新增、NDS 关联</td><td>季</td></tr></tbody></table><h3 id="b3-围护-机电-卫浴分项-envelope-mep-fixtures" tabindex="-1">B3. 围护/机电/卫浴分项（Envelope/MEP/Fixtures） <a class="header-anchor" href="#b3-围护-机电-卫浴分项-envelope-mep-fixtures" aria-label="Permalink to &quot;B3. 围护/机电/卫浴分项（Envelope/MEP/Fixtures）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞品</th><th>类别标杆理由</th><th>跟踪点</th><th>频率</th></tr></thead><tbody><tr><td><strong>围护：保温/门窗（EnergyStar/BAA）</strong></td><td>EnergyStar 认证门窗、UL 封堵</td><td>新效率等级、NAFS 修订</td><td>季</td></tr><tr><td><strong>MEP：汉尔姆</strong> 等中方对标</td><td>模块 MEP 快接（对标 snap MEP）</td><td>接口标准、预制率</td><td>月</td></tr><tr><td><strong>卫浴：sekisui/TOTO/汉尔姆 washroom</strong></td><td>预装整体卫浴模块</td><td>新品、ASME A112/WaterSense 合规</td><td>月</td></tr></tbody></table><h3 id="b4-检测-认证-第三方-qa-qaa-esr-服务方" tabindex="-1">B4. 检测/认证/第三方（QA/QAA/ESR 服务方） <a class="header-anchor" href="#b4-检测-认证-第三方-qa-qaa-esr-服务方" aria-label="Permalink to &quot;B4. 检测/认证/第三方（QA/QAA/ESR 服务方）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞品/服务方</th><th>类别标杆理由</th><th>跟踪点</th><th>频率</th></tr></thead><tbody><tr><td>ICC-ES（ESR 报告）</td><td>产品评估权威</td><td>新 ESR→模块化相关（13 34/13 42）</td><td>事件</td></tr><tr><td>HCD / IHCDA</td><td>加州工厂检验主管机构</td><td>Title 25 修订、检验政策</td><td>月</td></tr><tr><td>第三方 QAA（DAA/首件）</td><td>委派设计审图</td><td>加州执业 SE 库、审图流程异动</td><td>季</td></tr></tbody></table><hr><h2 id="c-标准动态跟踪-版本-修订异动-⭐" tabindex="-1">C. 标准动态跟踪（版本/修订异动）⭐ <a class="header-anchor" href="#c-标准动态跟踪-版本-修订异动-⭐" aria-label="Permalink to &quot;C. 标准动态跟踪（版本/修订异动）⭐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标准/规范</th><th>关注组织</th><th>修订周期</th><th>跟踪点</th><th>触发器/频率</th></tr></thead><tbody><tr><td><strong>IBC（国际建筑规范）</strong></td><td>ICC</td><td>3 年（2024→2027）</td><td>模块化章节变化（Ch.31?）</td><td>版本发布触发核对；季</td></tr><tr><td><strong>CBC（加州）</strong></td><td>CBSC/DOI</td><td>3 年</td><td>与 IBC 差异、州修正</td><td>季</td></tr><tr><td><strong>IRC（国际住宅规范）+ 州对应</strong></td><td>ICC/各州</td><td>3 年</td><td>HCD FBH 住宅级引用</td><td>季</td></tr><tr><td><strong>ASCE 7（荷载/抗震）</strong></td><td>ASCE</td><td>周期</td><td>地震/风/雪荷载更新</td><td>新版本触发；年</td></tr><tr><td><strong>AISC 360 / 341</strong></td><td>AISC</td><td>周期</td><td>钢结构设计/抗震修订</td><td>年</td></tr><tr><td><strong>AWS D1.1 / D1.8</strong></td><td>AWS</td><td>年</td><td>焊接/抗震补编新增</td><td>年</td></tr><tr><td><strong>NDS / WFCM</strong></td><td>AWC</td><td>周期</td><td>木结构设计更新</td><td>年</td></tr><tr><td><strong>ACI 318 / 533R / 355</strong></td><td>ACI</td><td>3 年(318)</td><td>混凝土/后锚固修订</td><td>年</td></tr><tr><td><strong>ASTM（A992/A36/A325/C1856/C1876 等）</strong></td><td>ASTM</td><td>年</td><td>版本号+性能变化</td><td>年</td></tr><tr><td><strong>NFPA 13/72/101</strong></td><td>NFPA</td><td>3 年</td><td>自动喷淋/报警/生命安全</td><td>年</td></tr><tr><td><strong>UL 1479 / UL 1703/1741</strong></td><td>UL</td><td>周期</td><td>防火封堵/光伏认证</td><td>年</td></tr><tr><td><strong>MasterFormat 章节编号</strong></td><td>CSI</td><td>周期</td><td>13 42/13 34 子章节变化</td><td>年</td></tr><tr><td><strong>ESR 报告（ICC-ES）</strong></td><td>ICC-ES</td><td>事件</td><td>新模块化/UHPC ESR</td><td>事件</td></tr><tr><td><strong>Title 25 §3032（HCD 检率）</strong></td><td>HCD</td><td>事件</td><td>检率/检验政策变化</td><td>事件</td></tr><tr><td><strong>HSC §19980（insignia）</strong></td><td>CA Legislature</td><td>立法</td><td>insignia 程序变化</td><td>事件</td></tr><tr><td><strong>HUD 3280/3282</strong></td><td>HUD</td><td>周期</td><td>制造住宅（默认排除，仅走该路径时）</td><td>事件</td></tr><tr><td><strong>ADA 2010 / CA Ch.11B</strong></td><td>DOJ/CA</td><td>周期</td><td>无障碍更新</td><td>年</td></tr></tbody></table><hr><h2 id="d-联邦-加州政策与进口动态-事件驱动-⭐" tabindex="-1">D. 联邦/加州政策与进口动态（事件驱动）⭐ <a class="header-anchor" href="#d-联邦-加州政策与进口动态-事件驱动-⭐" aria-label="Permalink to &quot;D. 联邦/加州政策与进口动态（事件驱动）⭐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关注点</th><th>触发器/频率</th></tr></thead><tbody><tr><td><strong>关税 Section 232（钢材/铝）</strong></td><td>钢铁关税变化→中方钢模块成本</td><td>事件（总统/ITC 决定）</td></tr><tr><td><strong>HUD/国家政策</strong></td><td>模块化住房联邦支持/新规</td><td>事件</td></tr><tr><td><strong>加州州级立法</strong></td><td>模块化 ADU/住房法案（工厂化）</td><td>立法季</td></tr><tr><td><strong>进口合规</strong></td><td>ISPM-15（木材除害）、CBP 申报、原产地</td><td>事件</td></tr><tr><td><strong>反倾销/贸易救济</strong></td><td>美对中建材调查</td><td>事件</td></tr></tbody></table><hr><h2 id="e-运营中台积累-l4-从-knowledge-channel-建筑图谱抽取-⭐" tabindex="-1">E. 运营中台积累（L4：从 knowledge-channel 建筑图谱抽取）⭐ <a class="header-anchor" href="#e-运营中台积累-l4-从-knowledge-channel-建筑图谱抽取-⭐" aria-label="Permalink to &quot;E. 运营中台积累（L4：从 knowledge-channel 建筑图谱抽取）⭐&quot;">​</a></h2><blockquote><p>按用户指示：在 <strong>knowledge-channel 的建筑图谱</strong>中，凡是打了 <strong>「Modular House」标签</strong>的节点/内容，<strong>有选择地发布共享</strong>到本平台（L1 知识库）。这是一条「知识回流」通道。</p></blockquote><ul><li><strong>机制</strong>：为建筑图谱 → Modular House 标签内容设置「精选/可发布」标记 → 定期同步到平台 L1。</li><li><strong>节奏</strong>：周度扫描新增标签内容，人工（或规则）筛选可公开项。</li><li><strong>与 spec-agent 大库关系</strong>：Modular 是 spec 大库的<strong>特例</strong>——L1 实际接入 spec-agent 母本，modular 作为特化视图，避免重复维护。</li></ul><hr><h2 id="f-实施步骤-对应「先出清单-再上-cron」" tabindex="-1">F. 实施步骤（对应「先出清单，再上 cron」） <a class="header-anchor" href="#f-实施步骤-对应「先出清单-再上-cron」" aria-label="Permalink to &quot;F. 实施步骤（对应「先出清单，再上 cron」）&quot;">​</a></h2><ol><li><strong>清单已出（本文件）</strong>：B/C/D/E 四类条目 = L2 雷达的完整跟踪面。</li><li><strong>下次动作</strong>：据此建 cron 作业——按条目的频率/触发器生成「标准异动简报 / 竞品月报」。</li><li><strong>落地 L1</strong>：把现有 11 份交付 + spec-agent 母本特例视图，组织成平台知识库专区。</li><li><strong>落地 L4</strong>：打通 knowledge-channel 建筑图谱的「Modular House」标签回流。</li></ol><hr><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>本文为平台 L2 雷达的<strong>跟踪清单</strong>（非简报本身）；上 cron 后，简报将按此清单条目自动核对并可能推送。</li><li>竞品「最先进对标」为<strong>动态字段</strong>，随新品/ESR/财务异动刷新，不只维护名单。</li><li>英文版字段预留 <code>EN</code>，供一键 i18n 切换。</li></ul>',32)])])}const b=d(e,[["render",n]]);export{c as __pageData,b as default};
